export function HumanInTheLoop({
  stepLabel = "{{stepLabel}}",
  status = "{{status}}",
  accent = "{{accent}}",
  showNote = {{showNote}},
}) {
  const isWaiting = status === "waiting";
  const marker = { waiting: accent, reviewed: "#2f8f5b", skipped: "#24143030" }[status] ?? "#24143030";
  const badge = {
    waiting: { color: "#241430", background: `color-mix(in srgb, ${accent} 40%, #FAF7F2)` },
    reviewed: { color: "#1c5c3a", background: "#A8E6C140" },
    skipped: { color: "#24143080", background: "#24143012", textDecoration: "line-through" },
  }[status] ?? { color: "#241430", background: "#24143012" };
  return (
    <div role="status" aria-live="polite" style={{ maxWidth: 420, padding: "14px 16px", borderRadius: 12, background: "#FAF7F2", color: "#241430", border: "1px solid #24143020", boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span aria-hidden="true" style={{ width: 10, height: 10, borderRadius: "50%", flex: "none", background: marker, boxShadow: isWaiting ? `0 0 0 4px color-mix(in srgb, ${accent} 30%, transparent)` : "none" }} />
        <span style={{ flex: 1, fontWeight: 600 }}>{stepLabel}</span>
        <span style={{ fontSize: 11, fontWeight: 700, textTransform: "capitalize", padding: "3px 9px", borderRadius: 999, ...badge }}>{status}</span>
      </div>
      {showNote && (
        <p style={{ margin: "10px 0 0", fontSize: 13, color: "#24143099", paddingLeft: 20 }}>A person must review this step before the workflow continues.</p>
      )}
    </div>
  );
}
